<?php
/**
 * WP SFTP Stream Backup — migration installer.
 *
 * Upload this single file into the (empty) web root of the new server and open it
 * in the browser. Paste the migration code generated by the plugin (unless it is
 * already embedded), enter its password and the new database: the backup is
 * streamed directly from the repository, nothing has to be downloaded first.
 *
 * Shell: WPSSB_MIGRATION_PASSWORD='...' php wpssb-installer.php --db-host=localhost \
 *        --db-name=NAME --db-user=USER --db-pass=PASS [--url=https://new-site] [--code=WPSSB1....] [--yes]
 *
 * This file and every temporary file delete themselves when the restore is complete.
 *
 * Coded by Radici Soluzioni Informatiche — https://radici.biz
 *
 * @package WPSSB
 */

define( 'WI_DIR', rtrim( str_replace( '\\', '/', __DIR__ ), '/' ) );
define( 'WI_ATTEMPTS', '.wpssb-installer-attempts.php' );
define( 'WI_MAX_ATTEMPTS', 10 );
define( 'WI_PREFIX', 'WPSSB1.' );
define( 'WI_ITERATIONS', 200000 );

function wi_h( $s ) {
	return htmlspecialchars( (string) $s, ENT_QUOTES, 'UTF-8' );
}

/** Bundled runtime and optional embedded code. */
function wi_bundle() {
	$raw    = @file_get_contents( __FILE__, false, null, __COMPILER_HALT_OFFSET__ );
	$plain  = ( false === $raw || '' === $raw ) ? false : @gzuncompress( $raw );
	$bundle = false === $plain ? null : json_decode( $plain, true );
	if ( ! is_array( $bundle ) || empty( $bundle['files']['run.php'] ) ) {
		throw new RuntimeException( 'This installer is damaged: download it again.' );
	}
	return $bundle;
}

function wi_decode_code( $code, $password ) {
	$code = (string) preg_replace( '/\s+/', '', (string) $code );
	if ( 0 !== strpos( $code, WI_PREFIX ) ) {
		throw new RuntimeException( 'This is not a WP SFTP Stream Backup migration code.' );
	}
	$raw = base64_decode( strtr( substr( $code, strlen( WI_PREFIX ) ), '-_', '+/' ), true );
	if ( false === $raw || strlen( $raw ) < 45 ) {
		throw new RuntimeException( 'The migration code is damaged.' );
	}
	$key   = hash_pbkdf2( 'sha256', (string) $password, substr( $raw, 0, 16 ), WI_ITERATIONS, 32, true );
	$plain = openssl_decrypt( substr( $raw, 44 ), 'aes-256-gcm', $key, OPENSSL_RAW_DATA, substr( $raw, 16, 12 ), substr( $raw, 28, 16 ), WI_PREFIX );
	$data  = false === $plain ? null : json_decode( $plain, true );
	if ( ! is_array( $data ) ) {
		throw new RuntimeException( 'Wrong password or damaged migration code.' );
	}
	if ( 1 !== ( isset( $data['v'] ) ? $data['v'] : 0 ) || empty( $data['repo'] ) || empty( $data['path'] ) ) {
		throw new RuntimeException( 'Unsupported migration code: update the installer.' );
	}
	if ( ! empty( $data['expires'] ) && (int) $data['expires'] < time() ) {
		throw new RuntimeException( 'The migration code expired on ' . gmdate( 'Y-m-d H:i', (int) $data['expires'] ) . ' UTC: generate a new one.' );
	}
	return $data;
}

/** Rate limit for password guesses. */
function wi_attempt() {
	$file = WI_DIR . '/' . WI_ATTEMPTS;
	$list = array();
	if ( is_file( $file ) ) {
		$raw  = (string) @file_get_contents( $file );
		$pos  = strpos( $raw, "\n" );
		$list = json_decode( false === $pos ? '' : substr( $raw, $pos + 1 ), true );
		$list = is_array( $list ) ? $list : array();
	}
	$now  = time();
	$list = array_values(
		array_filter(
			$list,
			function ( $t ) use ( $now ) {
				return (int) $t > $now - 3600;
			}
		)
	);
	if ( count( $list ) >= WI_MAX_ATTEMPTS ) {
		throw new RuntimeException( 'Too many attempts: wait an hour and try again.' );
	}
	$list[] = $now;
	@file_put_contents( $file, "<?php exit; ?>\n" . json_encode( $list ) );
}

function wi_requirements() {
	$missing = array();
	if ( version_compare( PHP_VERSION, '7.4', '<' ) ) {
		$missing[] = 'PHP 7.4 or newer (this server runs ' . PHP_VERSION . ')';
	}
	if ( ! function_exists( 'openssl_decrypt' ) ) {
		$missing[] = 'the OpenSSL extension';
	}
	if ( ! function_exists( 'inflate_init' ) || ! function_exists( 'gzuncompress' ) ) {
		$missing[] = 'the zlib extension';
	}
	if ( ! class_exists( 'mysqli' ) ) {
		$missing[] = 'the mysqli extension';
	}
	if ( ! is_writable( WI_DIR ) ) {
		$missing[] = 'a writable folder (' . WI_DIR . ')';
	}
	return $missing;
}

/** Files that are already in the destination folder (besides this installer). */
function wi_existing() {
	$out = array();
	foreach ( (array) @scandir( WI_DIR ) as $name ) {
		if ( ! in_array( $name, array( '.', '..', basename( __FILE__ ), WI_ATTEMPTS ), true ) && 0 !== strpos( (string) $name, 'wpssb-restore-' ) ) {
			$out[] = $name;
		}
	}
	return $out;
}

function wi_db_check( $host, $user, $pass, $name ) {
	mysqli_report( MYSQLI_REPORT_OFF );
	$port   = null;
	$socket = null;
	if ( preg_match( '/^(.+):(\d+)$/', $host, $m ) ) {
		$host = $m[1];
		$port = (int) $m[2];
	} elseif ( false !== strpos( $host, ':/' ) ) {
		list( $host, $socket ) = explode( ':', $host, 2 );
	}
	$db = mysqli_init();
	if ( ! @$db->real_connect( $host, $user, $pass, $name, $port, $socket ) ) {
		throw new RuntimeException( 'Database connection failed: ' . mysqli_connect_error() );
	}
	$db->close();
}

function wi_rmdir( $dir ) {
	if ( is_link( $dir ) || ! is_dir( $dir ) ) {
		@unlink( $dir );
		return;
	}
	foreach ( (array) @scandir( $dir ) as $name ) {
		if ( '.' !== $name && '..' !== $name && '' !== (string) $name ) {
			wi_rmdir( $dir . '/' . $name );
		}
	}
	@rmdir( $dir );
}

/**
 * Validates the input and extracts the restore runtime.
 *
 * @return array{dir:string,token:string}
 */
function wi_prepare( array $in, array $bundle ) {
	$missing = wi_requirements();
	if ( $missing ) {
		throw new RuntimeException( 'This server is missing ' . implode( ', ', $missing ) . '.' );
	}
	$code = '' !== (string) $bundle['code'] ? (string) $bundle['code'] : (string) $in['code'];
	if ( '' === trim( $code ) ) {
		throw new RuntimeException( 'Paste the migration code.' );
	}
	wi_attempt();
	$data = wi_decode_code( $code, (string) $in['password'] );
	$url  = rtrim( trim( (string) $in['url'] ), '/' );
	if ( '' !== $url && ( ! filter_var( $url, FILTER_VALIDATE_URL ) || ! preg_match( '#^https?://#i', $url ) ) ) {
		throw new RuntimeException( 'Enter a valid site address (http:// or https://).' );
	}
	foreach ( array( 'db_host', 'db_name', 'db_user' ) as $field ) {
		if ( '' === trim( (string) $in[ $field ] ) ) {
			throw new RuntimeException( 'Fill in all the database fields.' );
		}
	}
	if ( wi_existing() && empty( $in['overwrite'] ) ) {
		throw new RuntimeException( 'This folder is not empty: confirm that existing files may be overwritten.' );
	}
	wi_db_check( trim( (string) $in['db_host'] ), (string) $in['db_user'], (string) $in['db_pass'], trim( (string) $in['db_name'] ) );

	$name  = 'wpssb-restore-' . bin2hex( random_bytes( 8 ) );
	$token = bin2hex( random_bytes( 32 ) );
	$self  = basename( __FILE__ );
	$secret = array(
		'repo'            => $data['repo'],
		'path'            => $data['path'],
		'manifest_sha256' => isset( $data['manifest_sha256'] ) ? (string) $data['manifest_sha256'] : '',
		'opts'            => array(
			'url'            => $url,
			'db_host'        => trim( (string) $in['db_host'] ),
			'db_name'        => trim( (string) $in['db_name'] ),
			'db_user'        => (string) $in['db_user'],
			'db_pass'        => (string) $in['db_pass'],
			'keep'           => array( $self, WI_ATTEMPTS, $name ),
			'keep_config'    => false,
			'exclude'        => array(),
			'exclude_tables' => array(),
		),
	);
	$salt = bin2hex( random_bytes( 16 ) );
	$iv   = random_bytes( 12 );
	$tag  = '';
	$ct   = openssl_encrypt( (string) json_encode( $secret, JSON_UNESCAPED_SLASHES ), 'aes-256-gcm', hash_hmac( 'sha256', 'wpssb-runtime-config|' . $salt, $token, true ), OPENSSL_RAW_DATA, $iv, $tag );
	if ( false === $ct ) {
		throw new RuntimeException( 'Cannot encrypt the restore configuration.' );
	}
	$done   = ( '' !== $url ? $url : '' );
	$config = array(
		'v'          => 1,
		'mode'       => 'migration',
		'root'       => WI_DIR,
		'manifest'   => 'manifest.json',
		'cleanup'    => array( $self, WI_ATTEMPTS ),
		'done_url'   => '' !== $done ? $done . '/wp-admin/' : '../wp-admin/',
		'insecure'   => ! empty( $data['insecure'] ),
		'token_hash' => hash( 'sha256', $token ),
		'salt'       => $salt,
		'iv'         => base64_encode( $iv ),
		'tag'        => base64_encode( $tag ),
		'ct'         => base64_encode( $ct ),
	);
	$files               = $bundle['files'];
	$files['config.php'] = base64_encode( "<?php exit; ?>\n" . json_encode( $config, JSON_UNESCAPED_SLASHES ) );
	$dir                 = WI_DIR . '/' . $name;
	if ( ! @mkdir( $dir, 0755 ) ) {
		throw new RuntimeException( 'Cannot create the restore folder.' );
	}
	foreach ( $files as $rel => $b64 ) {
		$rel = str_replace( '\\', '/', (string) $rel );
		if ( '' === $rel || '/' === $rel[0] || preg_match( '#(^|/)\.\.?(/|$)#', $rel ) ) {
			wi_rmdir( $dir );
			throw new RuntimeException( 'This installer is damaged: download it again.' );
		}
		$target = $dir . '/' . $rel;
		if ( ( ! is_dir( dirname( $target ) ) && ! @mkdir( dirname( $target ), 0755, true ) ) || false === @file_put_contents( $target, base64_decode( $b64 ) ) ) {
			wi_rmdir( $dir );
			throw new RuntimeException( 'Cannot write the restore files.' );
		}
	}
	@chmod( $dir . '/config.php', 0600 );
	@unlink( WI_DIR . '/' . WI_ATTEMPTS );
	return array( 'dir' => $name, 'token' => $token );
}

function wi_cli_args( array $argv ) {
	$in = array( 'code' => '', 'url' => '', 'db_host' => '', 'db_name' => '', 'db_user' => '', 'db_pass' => '', 'overwrite' => false );
	foreach ( array_slice( $argv, 1 ) as $arg ) {
		if ( '--yes' === $arg ) {
			$in['overwrite'] = true;
		} elseif ( preg_match( '/^--([a-z-]+)=(.*)$/s', $arg, $m ) && array_key_exists( str_replace( '-', '_', $m[1] ), $in ) ) {
			$in[ str_replace( '-', '_', $m[1] ) ] = $m[2];
		} else {
			throw new RuntimeException( 'Unknown option ' . $arg );
		}
	}
	$in['password'] = (string) getenv( 'WPSSB_MIGRATION_PASSWORD' );
	return $in;
}

function wi_page( array $bundle, $error, array $in ) {
	$embedded = '' !== (string) $bundle['code'];
	$existing = wi_existing();
	$logo     = isset( $bundle['files']['logo.png'] ) ? 'data:image/png;base64,' . $bundle['files']['logo.png'] : '';
	$https    = ( ! empty( $_SERVER['HTTPS'] ) && 'off' !== strtolower( (string) $_SERVER['HTTPS'] ) ) || ( isset( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) && 'https' === strtolower( (string) $_SERVER['HTTP_X_FORWARDED_PROTO'] ) );
	$host     = isset( $_SERVER['HTTP_HOST'] ) ? preg_replace( '/[^A-Za-z0-9.:\[\]-]/', '', (string) $_SERVER['HTTP_HOST'] ) : 'localhost';
	$path     = rtrim( str_replace( '\\', '/', dirname( isset( $_SERVER['SCRIPT_NAME'] ) ? (string) $_SERVER['SCRIPT_NAME'] : '/' ) ), '/' );
	$url      = '' !== (string) $in['url'] ? $in['url'] : ( $https ? 'https://' : 'http://' ) . $host . $path;
	$missing  = wi_requirements();
	header( 'Content-Type: text/html; charset=utf-8' );
	?><!doctype html>
