header img{display:block;width:130px;height:auto}.content{padding:24px 32px}h1{font-size:24px;line-height:1.3;margin:0 0 16px}h2{font-size:16px;margin:24px 0 8px}
a{color:#375526}label{display:block;font-weight:600;margin:14px 0 4px}input[type=text],input[type=password],input[type=url],textarea{width:100%;padding:9px 11px;border:1px solid #b9c4b5;border-radius:6px;font:inherit}
textarea{font-family:ui-monospace,Consolas,monospace;font-size:12px;min-height:90px}.check{display:flex;gap:8px;align-items:flex-start;font-weight:400}
input:focus,textarea:focus{outline:2px solid #354c29;outline-offset:1px;border-color:#354c29}.hint{color:#59665e;font-size:13px;margin:4px 0 0}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}@media(max-width:600px){.grid{grid-template-columns:1fr}}
button{background:#354c29;color:#fff;border:1px solid #354c29;border-radius:6px;padding:10px 20px;margin:20px 0 0;cursor:pointer;font:inherit;font-weight:600}button:hover{background:#263d1c}
button:focus-visible{outline:2px solid #354c29;outline-offset:3px}
.err,.note{padding:14px 16px;border-radius:6px;overflow-wrap:anywhere;margin:16px 0}.err{background:#fcecec;border-left:4px solid #a02323}.note{background:#f1f5e8;border-left:4px solid #859a20}
