</style></head><body><main>
<header><div><p class="eyebrow">WP SFTP Stream Backup</p><strong>Migration installer</strong></div><?php if ( $logo ) : ?><a href="https://radici.biz" target="_blank" rel="noopener"><img src="<?php echo wi_h( $logo ); ?>" alt="Radici Soluzioni Informatiche"></a><?php endif; ?></header>
<div class="content">
