<p class="note">The backup is streamed directly from the repository into this folder and database: nothing has to be downloaded first. This installer deletes itself at the end.</p>
<?php if ( $missing ) : ?><div class="err">This server is missing <?php echo wi_h( implode( ', ', $missing ) ); ?>.</div><?php endif; ?>
<?php if ( '' !== (string) $error ) : ?><div class="err" role="alert"><?php echo wi_h( $error ); ?></div><?php endif; ?>
<form method="post" autocomplete="off">
<h2>Migration code</h2>
