<div><label for="db_name">Database name</label><input type="text" id="db_name" name="db_name" value="<?php echo wi_h( $in['db_name'] ); ?>" required></div>
<div><label for="db_user">Database user</label><input type="text" id="db_user" name="db_user" value="<?php echo wi_h( $in['db_user'] ); ?>" required></div>
