<label class="check"><input type="checkbox" name="overwrite" value="1" required> <span>This folder already contains <?php echo (int) count( $existing ); ?> items (<?php echo wi_h( implode( ', ', array_slice( $existing, 0, 5 ) ) . ( count( $existing ) > 5 ? ', …' : '' ) ); ?>): files with the same names will be overwritten.</span></label>
<?php endif; ?>
