</main></body></html>
	<?php
}

if ( defined( 'WPSSB_INSTALLER_LIBRARY_ONLY' ) ) {
	return;
}

error_reporting( E_ALL & ~E_DEPRECATED );
if ( PHP_SAPI === 'cli' ) {
	try {
		$bundle  = wi_bundle();
		$in      = wi_cli_args( $argv );
		$runtime = wi_prepare( $in, $bundle );
	} catch ( Throwable $e ) {
		fwrite( STDERR, 'ERROR: ' . $e->getMessage() . "\n" );
		exit( 1 );
	}
	echo 'Restore runtime created in ' . $runtime['dir'] . "\n";
	putenv( 'WPSSB_RUNTIME_TOKEN=' . $runtime['token'] );
	require WI_DIR . '/' . $runtime['dir'] . '/run.php';
	exit( 0 );
}

@ini_set( 'display_errors', '0' );
header( 'X-Robots-Tag: noindex, nofollow' );
header( 'Cache-Control: no-store' );
header( 'X-Frame-Options: DENY' );
header( 'Referrer-Policy: no-referrer' );
$wi_in = array( 'code' => '', 'password' => '', 'url' => '', 'db_host' => '', 'db_name' => '', 'db_user' => '', 'db_pass' => '', 'overwrite' => false );
try {
	$wi_bundle = wi_bundle();
} catch ( Throwable $e ) {
	http_response_code( 500 );
	exit( wi_h( $e->getMessage() ) );
}
$wi_error = '';
if ( 'POST' === ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : 'GET' ) ) {
	foreach ( array_keys( $wi_in ) as $wi_key ) {
		$wi_in[ $wi_key ] = isset( $_POST[ $wi_key ] ) && is_string( $_POST[ $wi_key ] ) ? $_POST[ $wi_key ] : $wi_in[ $wi_key ];
	}
	try {
		$wi_runtime = wi_prepare( $wi_in, $wi_bundle );
		header( 'Location: ' . $wi_runtime['dir'] . '/run.php#' . $wi_runtime['token'], true, 303 );
		exit;
	} catch ( Throwable $e ) {
		$wi_error = $e->getMessage();
	}
}
wi_page( $wi_bundle, $wi_error, $wi_in );
exit;
__halt_compiler();